* { box-sizing: border-box; }

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1cqw 0 4cqw;
}

.icon-btn {
  width: 10.5cqw;
  height: 10.5cqw;
  border-radius: 50%;
  background: var(--icon-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 1cqw 2cqw rgba(0,0,0,0.06);
  color: var(--icon-color);
  transition: all 0.3s ease;
}

.icon-btn:active {
  transform: scale(0.95);
}

.icon-btn svg {
  width: 5cqw;
  height: 5cqw;
}

.title {
  font-size: 4.8cqw;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.2px;
  transition: all 0.3s ease;
}

.translate-card {
  background: var(--card-bg);
  border-radius: 6cqw;
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 5cqw 5cqw 6cqw;
  box-shadow: 0 2cqw 6cqw rgba(0,0,0,0.04);
  transition: all 0.3s ease;
}

.section {
  display: flex;
  flex-direction: column;
}

.lang-selector {
  display: flex;
  align-items: center;
  gap: 1cqw;
  font-size: 3.4cqw;
  font-weight: 700;
  color: var(--lang-text);
  margin-bottom: 2cqw;
  transition: all 0.3s ease;
}

.native-select {
  appearance: none;
  -webkit-appearance: none;
  background: transparent;
  border: none;
  color: inherit;
  font-family: inherit;
  font-size: inherit;
  font-weight: inherit;
  padding: 0;
  margin: 0;
  outline: none;
  cursor: pointer;
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  max-width: 32cqw;
}

.native-select option {
  color: #000;
  font-size: 14px;
}

.lang-selector svg {
  width: 3.6cqw;
  height: 3.6cqw;
  color: var(--text-sub);
  transition: all 0.3s ease;
}

.target-lang {
  color: var(--text-sub);
}

.target-lang svg {
  color: var(--text-sub);
  opacity: 0.7;
}

.text-input-area {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 2cqw;
}

.text-main {
  font-size: 5cqw;
  font-weight: 700;
  color: var(--text-main);
  line-height: 1.4;
  letter-spacing: -0.3px;
  flex: 1;
  transition: all 0.3s ease;
}

.clear-btn {
  width: 5.5cqw;
  height: 5.5cqw;
  border-radius: 50%;
  background: var(--clear-btn-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 0.5cqw;
  color: #ffffff;
  transition: all 0.3s ease;
}

.clear-btn:active {
  transform: scale(0.9);
}

.clear-btn svg {
  width: 3.2cqw;
  height: 3.2cqw;
}

.divider-container {
  position: relative;
  height: 8cqw;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 1.5cqw 0 2.5cqw;
}

.line {
  position: absolute;
  width: 100%;
  height: 1px;
  background: var(--divider);
  transition: all 0.3s ease;
}

.swap-btn {
  width: 7.5cqw;
  height: 7.5cqw;
  border-radius: 50%;
  background: var(--swap-btn-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  z-index: 1;
  color: var(--text-sub);
  transition: all 0.3s ease;
}

.swap-btn:active {
  transform: rotate(180deg);
}

.swap-btn svg {
  width: 4cqw;
  height: 4cqw;
}

.text-result {
  font-size: 5cqw;
  font-weight: 700;
  color: var(--text-sub);
  line-height: 1.35;
  letter-spacing: -0.2px;
  transition: all 0.3s ease;
}

.history-panel {
  position: absolute;
  top: 0; left: 0; width: 100%; height: 100%;
  background: var(--bg-color);
  z-index: 100;
  display: flex;
  flex-direction: column;
  transform: translateY(100%);
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  box-sizing: border-box;
}

.history-panel.open {
  transform: translateY(0);
}

.history-header {
  display: flex;
  justify-content: space-between;
