}

/* 整体容器：完全透明 */
.widget {
  width: 100%; height: 100%;
  background: transparent;
  padding: 4px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

/* ── 气泡 + 箭头的外层包裹 ── */
.bubble-wrap {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center; /* 箭头水平居中 = 对准 Home */
}

/* 半透明白色气泡框，磨砂玻璃效果 */
.bubble {
  width: 100%;
  flex: 1;
  min-height: 0;
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-radius: 18px;
  padding: 6px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

/* 三角形箭头
   ▸ 颜色与气泡完全一致
   ▸ margin-top: -1px 向上咬入气泡 1px，消除抗锯齿缝隙，无缝连接 */
.arrow {
  flex-shrink: 0;
  margin-top: -1px;
  width: 0;
  height: 0;
  border-left:  12px solid transparent;
  border-right: 12px solid transparent;
  border-top:   12px solid rgba(255, 255, 255, 0.78);
}

/* ── 白色联系人卡片 ── */
