  flex: 1;
  min-height: 0;
  background: rgba(255, 255, 255, 0.92);
  border-radius: 12px;
  padding: 0 8px;
  display: flex;
  align-items: center;
  gap: 8px;
  overflow: hidden;
}

.avatar {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  background: #ddd8d0 center/cover no-repeat;
  flex-shrink: 0;
}

.info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.top-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.status       { font-size: 9px; color: #8e8e93; }
.badge        { font-size: 9px; color: #8e8e93; }
.badge b      { font-weight: 700; color: #1c1c1e; }

.name {
  font-size: 12px;
  font-weight: 700;
  color: #1c1c1e;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
