}

/* 外层容器 */
.music-widget-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: transparent;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  padding: 20px;
}

/* 顶部大圆形图片包装器 */
.main-record-wrapper {
  position: relative;
  z-index: 10;
  width: 100px;
  height: 100px;
  border-radius: 50%;
  border: 1px solid #ffffff;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0);
  background-color: #eee;
}

.main-record-img {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  object-fit: cover;
  display: block;
}

/* 底部半透明磨砂长方形面板 */
.glass-control-panel {
  position: relative;
  z-index: 5;
  margin-top: -10px;
  display: flex;
  flex-direction: row;
  align-items: center;
  width: 180px;
  height: 70px;
  padding: 5px;
  box-sizing: border-box;
  background: rgba(255, 255, 255, 0.25);
  backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(15px);
  border: 1px solid rgba(255, 255, 255, 0.45);
  border-radius: 12px;
  box-shadow: 0 10px 10px rgba(0, 0, 0, 0);
}

/* 左侧专辑封面区 */
.album-cover-box {
  width: 45px;
  height: 45px;
  border-radius: 50%;
  overflow: hidden;
  flex-shrink: 0;
  border: 1px solid rgba(255, 255, 255, 0.6);
  background-color: #ddd;
  margin-left: 5px;
}

.album-cover-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* =========================================
  右侧信息与控制区 (改为“画布”模式)
  ========================================= 
*/
.track-info-area {
  position: relative; /* 开启相对定位，作为内部绝对定位元素的基准框 */
  width: 120px;       /* 划定一个固定宽度 */
  height: 60px;       /* 划定一个固定高度 */
  margin-left: 10px;  /* 距离左边封面的距离 */
}

/* 1. 直接控制歌名位置 */
.text-song-title {
  position: absolute;
  top: 3px;         /* 【调这里】：距离画布顶部的距离 */
  left: 0px;        /* 【调这里】：距离画布左侧的距离 */
  font-size: 11px;
  font-weight: 600;
  color: #333;
  margin: 0;        /* 清除默认间距 */
}

/* 2. 直接控制歌手位置 */
.text-singer-name {
  position: absolute;
  top: 18px;        /* 【调这里】：直接设定位置，与歌名独立 */
  left: 0px;
  font-size: 10px;
  color: #666;
  margin: 0;
}

/* 3. 直接控制进度条位置 */
.progress-container {
  position: absolute;
  top: 35px;        /* 【调这里】：直接设定高度位置 */
  left: 0px;
  width: 100%;      /* 占满整个区域宽度 */
  height: 10px;
  display: flex;
  align-items: center;
}

.progress-bar-bg {
  width: 100%;
  height: 3px;
  background: rgba(0, 0, 0, 0.1);
  border-radius: 2px;
  position: relative;
}

.progress-bar-fill {
  width: 45%;
  height: 100%;
  background: #333;
  border-radius: 2px;
}

.progress-dot {
  width: 8px;
  height: 8px;
  background: #333;
  border-radius: 50%;
  position: absolute;
  top: 50%;
  left: 45%;
  transform: translate(-50%, -50%);
}

/* 4. 直接控制所有按钮的整体位置 */
.playback-controls {
  position: absolute;
  top: 45px;        /* 【调这里】：直接设定按钮组的高度位置 */
  left: 10px;       /* 【调这里】：微调左右位置 */
  width: 80px;      /* 按钮组的总宽度 */
  display: flex;
  flex-direction: row;
  justify-content: space-between; /* 按钮平均分布 */
  align-items: center;
}

.btn-icon {
  background: none;
  border: none;
  cursor: pointer;
  padding: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.1s ease;
}

.btn-icon:active {
  transform: scale(0.85);
}

/* =========================================
  纯 CSS 绘制的黑色播放器图标 (告别 emoji)
  ========================================= 
*/

/* 播放图标：黑色三角形 */
.icon-play {
  width: 0;
  height: 0;
  border-top: 5px solid transparent;
  border-bottom: 5px solid transparent;
  border-left: 8px solid #333;
}

/* 暂停图标：两条黑色竖线 */
.icon-pause {
  width: 8px;
  height: 10px;
  border-left: 2.5px solid #333;
  border-right: 2.5px solid #333;
  box-sizing: border-box;
  background: transparent;
  display: none; /* 默认隐藏 */
}

/* 上一首：一竖线 + 倒三角 */
.icon-prev {
  display: flex;
  align-items: center;
}
.icon-prev::before {
  content: "";
  width: 2px; height: 8px; background: #333; margin-right: 1px;
}
.icon-prev::after {
  content: "";
  width: 0; height: 0;
  border-top: 4px solid transparent;
  border-bottom: 4px solid transparent;
  border-right: 6px solid #333;
}

/* 下一首：正三角 + 一竖线 */
.icon-next {
  display: flex;
  align-items: center;
}
.icon-next::before {
  content: "";
  width: 0; height: 0;
  border-top: 4px solid transparent;
  border-bottom: 4px solid transparent;
  border-left: 6px solid #333; margin-right: 1px;
}
.icon-next::after {
  content: "";
  width: 2px; height: 8px; background: #333;
}

/* ==== 纯 CSS 播放/暂停交互逻辑 ==== */
#play-toggle:checked ~ .btn-play-pause .icon-play {
  display: none;
}
#play-toggle:checked ~ .btn-play-pause .icon-pause {
  display: block;
}

