.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1cqw 0 4cqw;
}

.icon-btn {
  width: 10.5cqw;
  height: 10.5cqw;
  border-radius: 50%;
  background: var(--icon-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 1cqw 2cqw rgba(0,0,0,0.06);
  color: var(--icon-color);
  transition: all 0.3s ease;
}

.icon-btn:active {
  transform: scale(0.95);
}

.icon-btn svg {
  width: 5cqw;
  height: 5cqw;
}

.title {
  font-size: 4.8cqw;
  font-weight: 700;
