  align-items: center;
  gap: 1cqw;
  font-size: 3.4cqw;
  font-weight: 700;
  color: var(--lang-text);
  margin-bottom: 2cqw;
  transition: all 0.3s ease;
}

.native-select {
  appearance: none;
  -webkit-appearance: none;
  background: transparent;
  border: none;
  color: inherit;
  font-family: inherit;
  font-size: inherit;
  font-weight: inherit;
  padding: 0;
  margin: 0;
  outline: none;
  cursor: pointer;
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  max-width: 32cqw;
}

.native-select option {
