  border-radius: 50%;
  box-shadow: 0 1cqw 3cqw rgba(0,0,0,0.06);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--icon-color);
  transition: all 0.3s ease;
}
.icon-btn:active {
  transform: scale(0.95);
}

.icon-btn svg {
  width: 5cqw;
  height: 5cqw;
}

.title {
  background: var(--card-bg);
  color: var(--text-main);
  padding: 2.5cqw 5cqw;
  border-radius: 6cqw;
  box-shadow: 0 1cqw 3cqw rgba(0,0,0,0.06);
