  font-weight: 600;
  display: flex;
  align-items: center;
  letter-spacing: 0.5px;
  transition: all 0.3s ease;
}

.date-container {
  display: flex;
  justify-content: center;
  margin-bottom: 8cqw;
}

.date-pill {
  background: var(--pill-bg);
  color: var(--text-muted);
  font-size: 3.2cqw;
  padding: 1.5cqw 3.5cqw;
  border-radius: 3.5cqw;
  font-weight: 500;
  letter-spacing: 1px;
  transition: all 0.3s ease;
}

.msg-list {
  display: flex;
  flex-direction: column;
  gap: 3.5cqw;
  align-self: center;
  max-width: 95cqw;
}

.msg {
  display: grid;
  grid-template-columns: max-content max-content auto;
  align-items: center;
  gap: 2.5cqw;
}

.time {
  font-size: 3.4cqw;
  color: var(--time-color);
  text-align: right;
  letter-spacing: 0.5px;
  transition: all 0.3s ease;
}

.status {
  width: 5.5cqw;
  height: 5.5cqw;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.3s ease;
}

.status.empty {
  border: 0.6cqw solid var(--status-border);
}

.status.sent {
  background: var(--status-bg);
}

.check-icon {
  stroke: var(--check-color);
  transition: all 0.3s ease;
}

.status.sent svg {
  width: 3.5cqw;
  height: 3.5cqw;
}

.bubble {
  background: var(--bubble-bg);
  color: var(--text-main);
  padding: 3.5cqw 5cqw;
  border-radius: 5cqw;
  font-size: 5cqw;
  line-height: 1.4;
  letter-spacing: 0.2px;
  font-weight: 500;
  transition: all 0.3s ease;
}

.bubble.strike {
  text-decoration: line-through;
  color: var(--text-muted);
}

