/* 主卡片容器：調整為高透圓角毛玻璃 */
.search-card {
  width: 100%;
  height: 52%;                      
  background: rgba(255, 255, 255, 0.4);  /* 核心修改：提高透明度，讓整體更通透 */
  backdrop-filter: blur(12px);       
  -webkit-backdrop-filter: blur(12px);
  border-radius: 18px !important;        /* 核心修改：加上精緻的圓角弧度 */
  box-shadow: none !important;        
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;                   
  overflow: hidden;
}

/* 中間搜尋文字區域 */
.search-main {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;                          
  padding: 0 8px;
}

/* 搜尋提示文字 */
