  color: #222222;                    
  letter-spacing: 0.3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* 中間放大鏡圖標 */
.search-hint-icon {
  width: 15px;                       
  height: 15px;
  fill: #1a1a1a;
  flex-shrink: 0;
}

/* 左右兩側功能圖標 */
.icon-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  flex-shrink: 0;
}

.icon-wrapper svg {
  width: 17px;                       
  height: 17px;
  fill: #222222;
}

/* 針對左側選單圖標進行微調 */
.left-icon svg {
  width: 16px;
  height: 16px;
}

/* 針對右側麥克風進行微調 */
.right-icon svg {
  width: 15px;
  height: 15px;
}

/* 整体容器：适配组件尺寸，防止旋转后内容被裁切 */
.my-custom-box {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  padding: 15px 8px;
  background: transparent;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 6px; /* 控制两个胶囊的垂直距离，越小越贴 */
}

/* 胶囊通用样式 */
.capsule {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 18px;
  background: rgba(230, 230, 230, 0.35);
  border-radius: 999px;
  height: 56px;
  width: 100%; /* 控制胶囊宽度，数值越大左边交叠越紧 */
}

/* 上胶囊：逆时针旋转2度，实现左低右高的倾斜，靠左对齐 */
.capsule-top {
  transform: rotate(-2deg);
  align-self: flex-start;
}

/* 下胶囊：顺时针旋转2度，实现左高右低的倾斜，靠右对齐 */
.capsule-bottom {
  transform: rotate(2deg);
  align-self: flex-end;
}

