/* 复制以下 CSS 贴入小组件样式栏 */
body { margin: 0; background: transparent; }

.widget {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 12px;
  box-sizing: border-box;
  font-family: -apple-system, "PingFang SC", sans-serif;
  background: transparent;
  position: relative;
  border-radius: inherit;
}

.polaroid-stack {
  position: relative;
  width: 100%;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 10px;
  cursor: grab;
  touch-action: pan-y;
  -webkit-tap-highlight-color: transparent;
}
.polaroid-stack:active {
  cursor: grabbing;
}

.polaroid {
  position: absolute;
  background: white;
  padding: 5px;
  border-radius: 6px;
  display: flex;
  flex-direction: column;
  transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
  width: 52%;
  box-sizing: border-box;
  cursor: pointer;
  -webkit-user-select: none;
  user-select: none;
}

.polaroid .photo {
  width: 100%;
  aspect-ratio: 1 / 1;
  background-color: #f0f0f0;
  background-position: center;
  background-size: cover;
  border-radius: 3px;
  pointer-events: none;
}

.polaroid .caption {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 0;
  font-size: 8px;
  color: #999;
  letter-spacing: 0.5px;
  margin-top: 0;
  opacity: 0;
  transition: all 0.3s;
  overflow: hidden;
  white-space: nowrap;
}

.polaroid.pos-center {
  transform: translateY(-8%) scale(1);
  z-index: 3;
  box-shadow: 0 8px 16px rgba(0,0,0,0.1);
}

.polaroid.pos-center .caption {
  opacity: 1;
  height: 20px;
  margin-top: 2px;
}

.polaroid.pos-left {
  transform: translateX(-48%) translateY(5%) rotate(-10deg) scale(0.92);
  z-index: 2;
  box-shadow: 0 4px 10px rgba(0,0,0,0.06);
}

.polaroid.pos-right {
  transform: translateX(48%) translateY(5%) rotate(10deg) scale(0.92);
  z-index: 1;
  box-shadow: 0 4px 10px rgba(0,0,0,0.06);
}

.dots {
  display: flex;
  gap: 4px;
  margin-top: 14px;
  margin-bottom: 10px;
}

.dot {
  width: 5px;
  height: 3px;
  background: rgba(255,255,255,0.5);
  border-radius: 2px;
  transition: all 0.3s;
}

.dot.active {
  width: 12px;
  background: white;
}

.status-bar {
  display: flex;
  width: 100%;
  justify-content: space-between;
  gap: 6px;
  margin-bottom: 2px;
}

.pill {
  flex: 1;
  background: rgba(255, 255, 255, 0.95);
  padding: 4px 0;
  border-radius: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 8px;
  font-weight: 600;
  color: #888;
  gap: 3px;
  box-shadow: 0 2px 6px rgba(0,0,0,0.04);
}

.pill svg {
  color: #aaa;
}

.interactive-pill {
  cursor: pointer;
  transition: transform 0.15s, background 0.15s;
  -webkit-tap-highlight-color: transparent;
}

.interactive-pill:active {
  transform: scale(0.93);
  background: rgba(255, 255, 255, 0.7);
}

.overlay {
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 10;
  display: flex;
  flex-direction: column;
  padding: 16px 14px;
  border-radius: 20px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s;
  box-sizing: border-box;
}

.overlay.active {
  opacity: 1;
  pointer-events: auto;
}

.overlay-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11px;
  font-weight: 700;
  color: #444;
  margin-bottom: 8px;
}

.overlay-close {
  cursor: pointer;
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  background: rgba(0,0,0,0.06);
  font-size: 14px;
  color: #666;
}

.overlay-close:active {
  background: rgba(0,0,0,0.1);
}

.overlay-list {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 5px;
  scrollbar-width: none;
}

.overlay-list::-webkit-scrollbar {
  display: none;
}

.overlay-item {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: #666;
  background: rgba(255,255,255,0.6);
  padding: 6px 8px;
  border-radius: 8px;
  box-shadow: 0 1px 2px rgba(0,0,0,0.04);
}

