  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

.widget-container {
  width: 100%;
  height: 100%;
  padding: 20px;
  box-sizing: border-box;
  position: relative; 
}

/* --- 上方方形照片 --- */
.photo-wrapper {
  width: 72%; 
  aspect-ratio: 1 / 1; 
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2); 
  background-color: #e0e0e0; 

  position: absolute;
  top: 25px;
  left: 20px;
  z-index: 1; 
}

.main-photo {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* --- 懸浮在右下角的選單 --- */
.menu-list {
  width: 50%; 
  background-color: rgba(245, 245, 245, 0.85); 
  border-radius: 12px;
  backdrop-filter: blur(25px); 
  -webkit-backdrop-filter: blur(25px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.12); 

  position: absolute;
  /* 【修改】大幅上移！現在選單頂部會對齊在容器 35% 的高度，深深壓在圖片上 */
  top: 35%; 
  right: 25px;
  z-index: 2; 
}

.menu-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px; 
  font-size: 14px; 
  font-weight: 400;
  color: #000000;
  border-bottom: 0.5px solid rgba(0, 0, 0, 0.1); 
}

.menu-item:last-child {
  border-bottom: none;
}

.menu-icon {
  width: 17px;
  height: 17px;
  color: #1a1a1a; 
}

/* --- iOS 特有的粗分隔帶 --- */
.separator {
  width: 100%;
  height: 6px; 
  background-color: rgba(0, 0, 0, 0.08); 
  border-bottom: 0.5px solid rgba(0, 0, 0, 0.1); 
}

/* --- 刪除項目的特殊樣式 --- */
.delete-item {
  color: #ff3b30; 
}

.delete-icon {
  color: #ff3b30;
}

/*⁣⁠​​⁠‍⁠⁠​​⁠‍‍​‍⁠‌‍⁠​‍⁠‍​‌‌​‌⁠‍​​​‍​​‌⁠⁠⁠‍‌‌​⁠‌⁠‌⁠‍⁠‍​​⁠​‌‌‌‌​‍⁠​​⁣ 外层容器：撑满整个 4x2 格子 */
.tri-photo {
  width: 100%;
  height: 100%;
  display: flex;
  gap: 8px;
  padding: 10px;
  box-sizing: border-box;
  background: transparent;
}

/* 每个图片的容器 */
.tri-photo .photo-box {
  flex: 1;
  background: #f2f2f2;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
}

/* 图片本身 */
.tri-photo .photo-box img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.mz-quote-widget, .mz-quote-widget * {
  -webkit-tap-highlight-color: transparent !important;
  box-sizing: border-box;
}

.mz-quote-widget {
  container-type: inline-size;
  width: 100%; height: 100%; 
  font-family: "STSong", "Songti SC", "SimSun", "AR PL UMing CN", serif;
  border-radius: clamp(16px, 6cqw, 24px);
  background: transparent;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: clamp(8px, 3cqw, 16px);
  overflow: hidden;
}

.quote-container {
  width: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: clamp(2px, 0.8cqw, 4px); 
}

.quote-line {
  display: flex; flex-wrap: wrap; align-items: baseline; justify-content: center; text-align: center;
  gap: clamp(1px, 0.4cqw, 3px);
}

.char-item.normal {
  font-size: var(--base-size); color: var(--c-text); font-weight: 500; opacity: 0.75;
  display: inline-block; -webkit-text-stroke: 0.2px var(--c-text);
}

.char-item.highlight {
  font-size: calc(var(--base-size) * var(--scale-val)); color: var(--c-text); font-weight: 700; opacity: 0.95;
  display: inline-block; -webkit-text-stroke: 0.4px var(--c-text); text-shadow: 0 2px 8px rgba(0,0,0,0.08);
  margin: 0 clamp(1px, 0.3cqw, 3px);
}

.char-item.english-first {
  font-size: calc(var(--base-size) * var(--scale-val)); font-weight: 800; -webkit-text-stroke: 0.5px var(--c-text); margin-right: 1px;
}

.char-item.sink { transform: translateY(6px); }
.char-item.rise { transform: translateY(-6px); }

.char-space { width: 6px; display: inline-block; }

body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 5vw; 
}

.widget-container {
  width: 100%;
  height: 100%;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end; 
  box-sizing: border-box;
  padding-bottom: 5%; 
  z-index: 0;
}

.widget-container::before {
  content: "";
  position: absolute;
  top: 0;
  /*⁣⁠‌‍⁠​​‌​⁠‍⁠‍‌​​​‌‌‍​‌​​⁠⁠⁠​‍‍​‍‌‌​‌‌‌⁠‍‌⁠‍‌​‌‍​‍‍‍⁠​‍​‌‍⁠⁠‍​⁠⁠⁠‌⁣ 【調整】設定為 5%，與下方白色卡片的左右邊距對齊 */
  left: 5%; 
  /* 【調整】寬度設為 90%，與白色卡片寬度保持一致 */
  width: 90%; 
  height: 50%; 
  background-image: url('{{bg}}');
  background-size: cover;
  background-position: center;
  /* 【調整】為背景圖頂部增加圓角，讓它看起來跟卡片是一體的 */
  border-radius: 6vw 6vw 0 0; 
  z-index: -1; 
}

.white-card {
  background: rgba(255, 255, 255, 0.95);
  width: 90%; 
  margin: 0 auto; 
  height: 52%; 
  border-radius: 6vw; 
  padding: 3vw 4vw;
  position: relative;
  display: flex;
  flex-direction: column;
  box-shadow: 0 2vw 4vw rgba(0, 0, 0, 0.08);
