.mz-review-widget {
  width: 100%; height: 100%; position: relative;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Helvetica Neue", sans-serif;
  box-sizing: border-box; overflow: hidden;
  border-radius: 24px;
}

.bg-media {
  position: absolute; top: 0; left: 0; 
  width: 100%; height: 100%; object-fit: cover; z-index: 0;
  pointer-events: none;
}
.bg-layer {
  position: absolute; top: 0; left: 0; 
  width: 100%; height: 100%; z-index: 1;
}

.content-layer {
  position: relative; z-index: 2;
  display: flex; flex-direction: column; 
  height: 100%;
  padding: 20px; 
  box-sizing: border-box;
}

/* --- 顶部区域：用户资料 --- */
.header-row {
  display: flex; flex-direction: row; align-items: center;
  margin-bottom: 20px; 
}

/* 头像框 */
.avatar-box {
  width: 48px; height: 48px;
  border-radius: 50%;
  border: 1px solid var(--avatar-border);
  overflow: hidden;
  flex-shrink: 0;
  position: relative;
}
.avatar-box img {
  width: 100%; height: 100%; object-fit: cover; display: block;
}
.avatar-placeholder {
  width: 100%; height: 100%; display: none;
  background-color: var(--theme-color); 
}

/* 用户名与认证 */
.user-info {
  flex: 1; 
  margin-left: 14px;
  display: flex; flex-direction: column; justify-content: center;
}
.username {
  color: var(--username-color); 
  font-size: var(--username-size); 
  font-weight: 800;
  line-height: 1.1;
}
.verified-badge {
  display: flex; align-items: center;
  color: var(--verified-color); 
  font-size: var(--verified-size); 
  font-weight: 900;
  margin-top: 4px;
}
.verified-badge svg {
  width: 14px; height: 14px; margin-right: 4px;
}

/* 评论数 */
.review-count {
  display: flex; align-items: center;
  color: var(--review-count-color); 
  font-size: var(--review-count-size); 
  font-weight: 900;
}
.review-count svg {
  width: 16px; height: 16px; margin-right: 4px;
}

/* --- 中部：评论气泡框 --- */
.review-bubble {
  flex: 1;
  position: relative;
  background-color: var(--card-bg); 
  border: 1.5px solid var(--border-color); 
  border-radius: 8px;
  padding: 12px;
  display: flex; flex-direction: column;
  min-height: 0;
}

/* 气泡向上指的小三角形 */
.bubble-triangle {
  position: absolute;
  top: -8px; 
  left: 20px; 
  width: 14px; height: 14px;
  background-color: var(--card-bg); 
  border-top: 1.5px solid var(--border-color); 
  border-left: 1.5px solid var(--border-color);
  transform: rotate(45deg);
  border-top-left-radius: 2px;
}

/* 星星与日期栏 */
.review-meta {
  display: flex; flex-direction: row; align-items: center;
  margin-bottom: 10px;
}
.stars {
  display: flex; gap: 3px; margin-right: 8px;
}
.star-box {
  width: 15px; height: 15px;
  background-color: var(--theme-color);
  display: flex; align-items: center; justify-content: center;
}
/* 🌟 核心更新：SVG 图标使用颜色变量 */
.star-box svg {
  width: 12px; height: 12px;
  color: var(--star-inner-color); 
}

.review-date {
  color: var(--sub-text-color);
  font-size: 12px; font-weight: 600;
}
.spacer { flex: 1; }

.report-btn {
  display: flex; align-items: center;
  color: #C0C0C0;
  font-size: 10px; font-weight: bold;
}
.report-btn svg {
  width: 12px; height: 12px; margin-right: 2px;
}

/* 评论标题/正文 */
.review-title {
  color: var(--title-color); 
  font-size: var(--title-size); 
  font-weight: 900;
  margin-bottom: 12px;
  line-height: 1.2;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  flex-shrink: 0;
}

/* 评论主图 */
.post-image-box {
  width: 100%; flex: 1;
