  flex-direction: column;
  justify-content: center;
  overflow: hidden;

  /* 增加气泡外下方的动态间距 */
  margin-bottom: 2%; 
  margin-top: 2%;
}

.chat-text {
  font-size: 11px;
  color: var(--text-color); 
  line-height: 1.4;
  font-weight: 500;
  word-wrap: break-word;
  word-break: break-word; 

  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4; /* 因为边距缩小了，这里可以容纳更多行，放宽到4行 */
  overflow: hidden;
}

.toolbar {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  background-color: var(--toolbar-bg); 
  border: 1px solid rgba(0, 0, 0, 0.03);
  border-radius: 12px;
