.chat-container.theme-purple-white {
  --app-bg: #f4f0fa;
  --card-bg: #ffffff;
  --text-main: #322543;
  --text-muted: #847596;
  --time-color: #9f91b3;
  --pill-bg: #e8e0f5;
  --bubble-bg: #dcd0ef;
  --status-border: #c2b1db;
