  --bubble-avatar-gap: -1px;        /* 气泡离头像的距离 */

  /* 顶栏高度 */
  --header-height: 80px;           /* 顶栏基础内容高度 */
  --header-sub-height: 38px;       /* 顶栏下方副栏/关注条高度 */

  /* 底栏高度 */
  --footer-input-height: 34px;     /* 底栏输入行高度 */
  --footer-base-padding: 39px;     /* 消息列表底栏基础安全避让高 */

  /* 媒体与图片配置变量 */
  --media-sticker-max-size: 110px;       /* 表情包最大尺寸 */
  --media-image-max-size: 150px;         /* 普通图片最大尺寸 */
  --media-image-radius: 4px;             /* 图片圆角大小 */
  --media-sticker-offset-top: 0.5px;     /* 表情包顶部微调偏移 */

  /* 转账文案 */
  --transfer-msg-pending: "人 咪 很 喜 欢 你 ！";
  --transfer-msg-done: "咪吃饱啦，感谢投喂";
  --transfer-msg-rejected: "咪就一颗心你随便伤";
  --transfer-msg-expired: "不要咪了吗";

  /* 旁白底部避让 */
  --narration-bottom-gap: 25px;

  /* 翻译内容 */
  --translation-always-show: 1;

  /* 位置卡片 (日间) */
  --location-card-radius: 6px !important;
  --location-card-border: none !important;
  --location-card-shadow: none !important;
  --location-card-bg: #ffffff !important;
}

