    /* 🐕 */ --rp-status-top: 92%;       /* ← 状态文字中心的高度位置 */
    /* 🐕 */ --rp-text-display: none;    /* ← 图片上没有祝福语时改成 block */
}

/* --- 0. 去掉外层古早气泡壳 --- */
div.chat-detail-screen .bubble-me-custom:has(.msg-redpacket-card),
div.chat-detail-screen .msg-plain-me:has(.msg-redpacket-card),
div.chat-detail-screen .bubble-them-custom:has(.msg-redpacket-card),
div.chat-detail-screen .msg-plain-them:has(.msg-redpacket-card) {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
}
div.chat-detail-screen .bubble-me-custom:has(.msg-redpacket-card)::before,
div.chat-detail-screen .bubble-me-custom:has(.msg-redpacket-card)::after,
div.chat-detail-screen .msg-plain-me:has(.msg-redpacket-card)::before,
div.chat-detail-screen .msg-plain-me:has(.msg-redpacket-card)::after,
div.chat-detail-screen .bubble-them-custom:has(.msg-redpacket-card)::before,
div.chat-detail-screen .bubble-them-custom:has(.msg-redpacket-card)::after,
div.chat-detail-screen .msg-plain-them:has(.msg-redpacket-card)::before,
div.chat-detail-screen .msg-plain-them:has(.msg-redpacket-card)::after {
    display: none !important;
}

/* --- 1. 卡片本体：红包图片做背景 --- */
div.chat-detail-screen .msg-redpacket-card {
    display: block !important;
    position: relative !important;
    width: var(--rp-w) !important;
    height: var(--rp-h) !important;
    min-width: 0 !important;
    min-height: 0 !important;
    margin: 0 0 30px 0 !important;      /* 底部留给「普通红包」标签 */
    padding: 0 !important;
    box-sizing: border-box !important;
    background: var(--rp-img) center / cover no-repeat !important;
    border: none !important;
    border-radius: 8px !important;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.12) !important;
    overflow: visible !important;       /* 标签在卡片外面，不能裁 */
    filter: none !important;
    animation: none !important;
    transform: none !important;
    cursor: pointer !important;
    -webkit-tap-highlight-color: transparent !important;
}

/* --- 2. 原生内容全部隐藏（不挡点击，点卡片照样能拆） --- */
div.chat-detail-screen .msg-redpacket-card * {
    visibility: hidden !important;
}

/* --- 3. 「開」下面的状态文字 --- */
div.chat-detail-screen .msg-redpacket-card::before {
    content: "已领取" !important;       /* 已拆封的默认文案 */
    display: block !important;
    position: absolute !important;
    z-index: 2 !important;
    left: 0 !important;
    right: 0 !important;
    top: calc(var(--rp-status-top) - 8px) !important;   /* 行高 16 的一半 */
    bottom: auto !important;
    width: auto !important;
    height: 16px !important;
    margin: 0 !important;
    padding: 0 !important;
    background: none !important;
    border: none !important;
    box-shadow: none !important;
    text-align: center !important;
    font-size: 12px !important;
    font-weight: 500 !important;
