    /* 🐕 */ --sim-c: url("https://i.postimg.cc/KjGz7Xdy/IMG-5628.jpg");
    /* 🐕 */ --sim-d: url("https://i.postimg.cc/zvzBwm95/IMG-5629.jpg");
    /* 🐕 */ --sim-e: url("https://i.postimg.cc/1Xmt0xLm/IMG-5630.jpg");
