/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【翻译】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* ═══════════════════════════════════════════════
   翻译 · 气泡外字幕式
   - 白字黑描边，悬在气泡下边缘，不占位置
   - 对方：用气泡外的 .msg-translation-detached-them
   - 我方：App 只给气泡内的 .msg-translation-out，定位到气泡下方
   - 自动展开关闭时：点气泡显示，再点收起
   ═══════════════════════════════════════════════ */

div.chat-detail-screen {
  /* 🐕 */ --tr-size: 13px;
  /* 🐕 */ --tr-offset: -3px;
  /* 🐕 */ --tr-indent: 12px;
  /* 🐕 */ --tr-max-w: 240px;
  /* 🐕 */ --tr-stroke: #000000;
  /* 🐕 */ --tr-color: #FFFFFF;

  /* 🐕 */ --translation-btn-display: block;
  /* 🐕 */ --translation-margin: 0;
  /* 🐕 */ --translation-padding
  /* 🐕 */ --translation-padding: 0;
  /* 🐕 */ --translation-bg: transparent;
}

/* 0. 有翻译的气泡：去掉 flex 间距和正文的下边距，避免底部留空 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-translation-wrapper),
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them) :has(> .msg-translation-wrapper) {
  gap: 0 !important;
  row-gap: 0 !important;
}
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them) :has(+ .msg-translation-wrapper) {
  margin-bottom: 0 !important;
}

/* 1. 气泡内翻译容器：绝对定位铺满气泡，移出排版，不占高度 */
div.chat-detail-screen .msg-translation-wrapper {
  position: absolute !important;
  inset: 0 !important;
  display: block !important;
  width: auto !important;
  height: auto !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  border-radius: inherit !important;
  background: none !important;
  box-shadow: none !important;
  overflow: visible !important;
  pointer-events: none !important;
  z-index: 2 !important;
}

/* 「查看翻译」按钮：铺满容器的透明点击层 */
div.chat-detail-screen .msg-translation-wrapper .msg-translation-btn {
  display: block !important;
  position: absolute !important;
  inset: 0 !important;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  border-radius: inherit !important;
  background: transparent !important;
  box-shadow: none !important;
  color: transparent !important;
  font-size: 0 !important;
  opacity: 1 !important;
  visibility: visible !important;
  pointer-events: auto !important;
  z-index: 2 !important;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent !important;
}
div.chat-detail-screen .msg-translation-wrapper .msg-translation-btn *,
div.chat-detail-screen .msg-translation-wrapper .msg-translation-btn::before,
div.chat-detail-screen .msg-translation-wrapper .msg-translation-btn::after {
  display: none !important;
}

/* 气泡里的引用块放到点击层上面 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-translation-btn) .msg-reply-block {
  position: relative !important;
  z-index: 3 !important;
}

/* 2. 对方：气泡内的译文隐藏 */
div.chat-detail-screen .msg-translation-wrapper:not(.msg-translation-out) .msg-translation-content {
  display: none !important;
}

/* 3. 我方：译文定位到气泡下边缘 */
div.chat-detail-screen .msg-translation-wrapper.msg-translation-out .msg-translation-content {
  position: absolute !important;
  top: calc(100% + 1px + var(--tr-offset)) !important;
  right: calc(var(--tr-indent) - 1px) !important;
  left: auto !important;
  bottom: auto !important;
  width: max-content !important;
  max-width: var(--tr-max-w) !important;
  margin: 0 !important;
  padding: 0 !important;
  z-index: 4 !important;
  pointer-events: none !important;
}

/* 4. 对方：气泡外独立翻译块，高度为 0，不占位置 */
div.chat-detail-screen .msg-translation-detached {
  display: block !important;
  position: relative !important;
  top: calc(-9px + var(--tr-offset)) !important;
  z-index: 3 !important;
  width: fit-content !important;
  max-width: var(--tr-max-w) !important;
  height: 0 !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: visible !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  pointer-events: none !important;
}
div.chat-detail-screen .msg-translation-detached::before,
div.chat-detail-screen .msg-translation-detached::after {
  display: none !important;
}
div.chat-detail-screen .msg-translation-detached-them {
  align-self: flex-start !important;
  margin-left: var(--tr-indent) !important;
}
div.chat-detail-screen .msg-translation-detached-me {
  align-self: flex-end !important;
  margin-right: var(--tr-indent) !important;
}

/* 5. 字幕文字（双方通用）：白字 + 8 方向黑描边 */
div.chat-detail-screen .msg-translation-detached-content,
div.chat-detail-screen .msg-translation-detached-content *,
div.chat-detail-screen .msg-translation-wrapper.msg-translation-out .msg-translation-content,
div.chat-detail-screen .msg-translation-wrapper.msg-translation-out .msg-translation-content * {
  background: none !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  color: var(--tr-color) !important;
  font-size: var(--tr-size) !important;
  font-weight: 600 !important;
  line-height: 1.3 !important;
  text-align: left !important;
  white-space: normal !important;
  word-break: break-word !important;
  text-shadow:
    -1px -1px 0 var(--tr-stroke),  0   -1px 0 var(--tr-stroke),
     1px -1px 0 var(--tr-stroke),  1px  0   0 var(--tr-stroke),
     1px  1px 0 var(--tr-stroke),  0    1px 0 var(--tr-stroke),
    -1px  1px 0 var(--tr-stroke), -1px  0   0 var(--tr-stroke),
     0 0 2px var(--tr-stroke) !important;
  -webkit-font-smoothing: antialiased !important;
}
div.chat-detail-screen .msg-translation-detached-content {
  margin: 0 !important;
  padding: 0 !important;
}

/* 6. 去掉装饰 */
div.chat-detail-screen .msg-translation-detached-content::before,
div.chat-detail-screen .msg-translation-detached-content::after,
div.chat-detail-screen .msg-translation-out .msg-translation-content::before,
div.chat-detail-screen .msg-translation-out .msg-translation-content::after,
div.chat-detail-screen .msg-translation-detached :is(svg, img) {
  display: none !important;
}
/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【时间戳与旁白】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* ===== 时间 13px + 旁白紧跟时间时靠近 ===== */
div.chat-detail-screen {
  /* 🐕 */ --timestamp-size: 13px;
  /* 🐕 */ --narr-pull: 16px;
