/* 旁白紧跟在时间后面时，往上收 */
div.chat-detail-screen [class*="timestamp"] + .msg-narration-custom,
div.chat-detail-screen [class*="timestamp"] + :has(.msg-narration-custom) .msg-narration-custom {
