/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【头像与挂件】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* ═══════════════════════════════════════════════
   头像 · 36px + 双方挂件
   ═══════════════════════════════════════════════ */

:root {
  /* 🐕 */ --avatar-size: 36px;
}

div.chat-detail-screen {
  /* 🐕 */ --pend-scale: 1.2;

  /* 🐕 */ --pend-me-img: url("https://i.postimg.cc/CKCxr2cc/IMG-5711.png");
  /* 🐕 */ --pend-me-r: -0.10;
  /* 🐕 */ --pend-me-y: -0.30;
  /* 🐕 */ --pend-me-w: 0.65;
  /* 🐕 */ --pend-me-h: 0.50;

  /* 🐕 */ --pend-them-img: url("https://i.postimg.cc/sgtWCpjn/IMG-5701.png");
  /* 🐕 */ --pend-them-x: -0.20;
  /* 🐕 */ --pend-them-y: -0.20;
  /* 🐕 */ --pend-them-w: 0.42;
  /* 🐕 */ --pend-them-h: 0.61;
