/* 1. 头像容器 */
div.chat-detail-screen .msg-avatar-them-container,
div.chat-detail-screen .msg-avatar-me-container,
div.chat-detail-screen .msg-avatar-container {
  flex: 0 0 var(--avatar-size) !important;
  width: var(--avatar-size) !important;
  height: var(--avatar-size) !important;
  min-width: var(--avatar-size) !important;
  min-height: var(--avatar-size) !important;
  max-width: var(--avatar-size) !important;
  max-height: var(--avatar-size) !important;
}

/* 2. 头像内层 + 图片 */
div.chat-detail-screen .msg-avatar-them-inner,
div.chat-detail-screen .msg-avatar-me-inner,
div.chat-detail-screen .msg-avatar-custom,
div.chat-detail-screen .msg-avatar-them-container img,
div.chat-detail-screen .msg-avatar-me-container img,
div.chat-detail-screen .msg-avatar-container img {
