  left: 50% !important;
  transform: translate(-50%, -50%) !important;
}

/* 4. 挂件定位基准 */
div.chat-detail-screen .msg-avatar-me-container,
div.chat-detail-screen .msg-avatar-them-container {
  position: relative !important;
  overflow: visible !important;
}

/* 挂件公共样式 */
div.chat-detail-screen .msg-avatar-me-container::after,
div.chat-detail-screen .msg-avatar-them-container::after {
  content: "" !important;
  position: absolute !important;
  display: block !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: contain !important;
  pointer-events: none !important;
  z-index: 5 !important;
}

/* 我方「?」：以右上角为基准 */
div.chat-detail-screen .msg-avatar-me-container::after {
  background-image: var(--pend-me-img) !important;
  left:   auto !important;
  right:  calc(var(--avatar-size) * var(--pend-me-r)) !important;
  top:    calc(var(--avatar-size) * var(--pend-me-y)) !important;
