.header-btn-phone,
.header-btn-video {
  position: relative !important;
  top: 0px !important; /* 在这里改数字，正数往下，负数往上 */
}

  /* 底栏图标 (保留小狗图标) */
  --plus-btn-icon: url('https://i.postimg.cc/9MTrJ4HQ/retouch-2026080715061723.png');
  --mic-btn-icon: url('https://i.postimg.cc/9MTrJ4HQ/retouch-2026080715061723.png');
