============================================ */
.msg-bubble-wrapper:has(.bubble.sticker),
.msg-bubble-wrapper:has(.bubble.image),
.msg-bubble-wrapper:has(img),
.bubble.sticker,
.bubble.image,
.msg-image-wrapper,
.chat-room .message-row .bubble-wrap .bubble.sticker,
.chat-room .message-row .bubble-wrap .bubble.image {
