}

/* ============================================
   ★ 100% 原创手搓：全分离式气泡系统 ★
============================================ */

/* ---------- A. 语音分离 ---------- */
.bubble-me-custom:has(.voice-msg),
.bubble-them-custom:has(.voice-msg) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}

.voice-msg {
  position: relative !important; 
  display: flex !important;
  flex-direction: column !important;
  gap: 6px !important; 
}
.msg-them .voice-msg { align-items: flex-start !important; }
.msg-me .voice-msg { align-items: flex-end !important; }

.voice-controls-row {
  display: flex !important;
  align-items: center !important;
  width: 125px !important;
  min-width: 125px !important;
  max-width: 125px !important;
  gap: 6px !important;
  padding: 4px 10px !important;
  border-radius: var(--bubble-me-radius) !important;
}
.msg-me .voice-controls-row {
  background: var(--bubble-me-bg) !important;
  border: none !important;
  box-shadow: var(--bubble-me-shadow) !important;
}
.msg-them .voice-controls-row {
  background: var(--bubble-them-bg) !important;
  border: none !important;
  box-shadow: var(--bubble-them-shadow) !important;
}

/* 播放键：使用 mask-image 给纯黑音符素材填入灰粉色 */
.voice-play-btn {
  width: 24px !important;
  height: 24px !important;
  border-radius: 0 !important;
  position: relative !important;
  box-shadow: none !important;
  flex-shrink: 0 !important;
  border: none !important;

  /* 用背景色作为实际显示颜色，色值对齐时长文字的 #8c737c */
  background-color: #8c737c !important;
  background-image: none !important; 

  /* 用你的素材作为遮罩剪切出音符形状 */
  -webkit-mask-image: url('https://i.postimg.cc/W4mY00Q1/zi-yuan-80.png') !important;
  mask-image: url('https://i.postimg.cc/W4mY00Q1/zi-yuan-80.png') !important;
  -webkit-mask-size: contain !important;
  mask-size: contain !important;
  -webkit-mask-position: center !important;
  mask-position: center !important;
  -webkit-mask-repeat: no-repeat !important;
  mask-repeat: no-repeat !important;
}
.voice-play-btn svg,
.voice-play-btn::after,
.voice-play-btn::before { 
  display: none !important; 
  content: none !important;
}

.voice-waveform {
  flex: 0 0 35px !important; 
  width: 35px !important;
  min-width: 35px !important;
  max-width: 35px !important;
  height: 14px !important; 
  overflow: hidden !important;
  mask-image: linear-gradient(to right, #000 70%, transparent 100%);
  -webkit-mask-image: linear-gradient(to right, #000 70%, transparent 100%);
}

.voice-duration {
  font-size: 11px !important;
  margin-left: auto !important; 
}

.voice-download-btn {
