.chat-detail-screen :is(#chat-message-list-root,.chat-messages-area) {padding-bottom:36px!important;}
.chat-detail-screen :is(.bubble-me-custom,.bubble-them-custom,.msg-plain-me,.msg-plain-them):not(:has(.msg-transfer-card,.msg-videocall-card,img,video)) {
