.chat-detail-screen :is(.bubble-me-custom,.bubble-them-custom,.msg-plain-me,.msg-plain-them):not(:has(.msg-transfer-card,.msg-videocall-card,img,video))::before {
  -webkit-mask-image:linear-gradient(#000,#000),var(--nt-paper-cut);
  mask-image:linear-gradient(#000,#000),var(--nt-paper-cut);
  -webkit-mask-size:100% calc(100% - 9px),180px 10px;
  mask-size:100% calc(100% - 9px),180px 10px;
  -webkit-mask-position:left top,center bottom;
  mask-position:left top,center bottom;
  -webkit-mask-repeat:no-repeat,repeat-x;mask-repeat:no-repeat,repeat-x;
  animation:nt-surf-edge 2.3s cubic-bezier(.22,.62,.27,1) .06s 1 both!important;
