.chat-detail-screen :is(.bubble-me-custom,.bubble-them-custom,.msg-plain-me,.msg-plain-them):not(:has(.msg-transfer-card,.msg-videocall-card,img,video))::after {
  left:2px;right:2px;bottom:0;height:14px;
