.msg-avatar-them-inner, 
.msg-avatar-me-inner, 
.msg-avatar-custom, 
.msg-avatar-container img {
  border-radius: 50% !important;
  box-shadow: 0 0 0 1.5px #ffffff, 0 0 0 2.5px #f0e0e8 !important;
  border: none !important;
}

/* ============================================
   ★ 思维链：去除繁琐装饰，变成纯净可爱英文胶囊 ★
============================================ */
/* 隐藏原生箭头和 emoji */
.nuo-thinking-arrow,
.nuo-thinking-icon {
  display: none !important;
}

/* 替换文案为可爱英文词汇 */
.nuo-thinking-label {
  font-size: 0 !important; 
}
.nuo-thinking-label::after {
  content: "Dreaming...";
  font-size: 13px !important;
  font-style: italic !important;
  letter-spacing: 0.5px !important;
  color: #df9cb3 !important;
}

/* ============================================
   ★ 图片与表情包终极隔离净化（绝对无底色无贴纸） ★
============================================ */
.msg-bubble-wrapper:has(.bubble.sticker),
.msg-bubble-wrapper:has(.bubble.image),
.msg-bubble-wrapper:has(img),
.bubble.sticker,
.bubble.image,
.msg-image-wrapper,
.chat-room .message-row .bubble-wrap .bubble.sticker,
.chat-room .message-row .bubble-wrap .bubble.image {
  background: transparent !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}

.msg-bubble-wrapper:has(.bubble.sticker) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.bubble.sticker) .bubble-them-custom::before,
.msg-bubble-wrapper:has(.bubble.image) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.bubble.image) .bubble-them-custom::before,
.bubble.sticker::before,
.bubble.image::before,
.msg-image-wrapper::before,
.bubble-me-custom:has(img)::before,
.bubble-them-custom:has(img)::before {
  display: none !important;
  content: none !important;
}

/* ============================================
   ★ 100% 原创手搓：全分离式气泡系统 ★
============================================ */

/* ---------- A. 语音分离 ---------- */
.bubble-me-custom:has(.voice-msg),
.bubble-them-custom:has(.voice-msg) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}

.voice-msg {
  position: relative !important; 
  display: flex !important;
  flex-direction: column !important;
  gap: 6px !important; 
}
.msg-them .voice-msg { align-items: flex-start !important; }
.msg-me .voice-msg { align-items: flex-end !important; }

.voice-controls-row {
  display: flex !important;
  align-items: center !important;
  width: 125px !important;
  min-width: 125px !important;
  max-width: 125px !important;
  gap: 6px !important;
  padding: 4px 10px !important;
  border-radius: var(--bubble-me-radius) !important;
}
.msg-me .voice-controls-row {
  background: var(--bubble-me-bg) !important;
  border: none !important;
  box-shadow: var(--bubble-me-shadow) !important;
}
.msg-them .voice-controls-row {
  background: var(--bubble-them-bg) !important;
  border: none !important;
  box-shadow: var(--bubble-them-shadow) !important;
}

/* 播放键：使用 mask-image 给纯黑音符素材填入灰粉色 */
.voice-play-btn {
  width: 24px !important;
  height: 24px !important;
  border-radius: 0 !important;
  position: relative !important;
  box-shadow: none !important;
  flex-shrink: 0 !important;
  border: none !important;

  /* 用背景色作为实际显示颜色，色值对齐时长文字的 #8c737c */
  background-color: #8c737c !important;
  background-image: none !important; 

  /* 用你的素材作为遮罩剪切出音符形状 */
  -webkit-mask-image: url('https://i.postimg.cc/W4mY00Q1/zi-yuan-80.png') !important;
  mask-image: url('https://i.postimg.cc/W4mY00Q1/zi-yuan-80.png') !important;
  -webkit-mask-size: contain !important;
  mask-size: contain !important;
  -webkit-mask-position: center !important;
  mask-position: center !important;
  -webkit-mask-repeat: no-repeat !important;
  mask-repeat: no-repeat !important;
}
.voice-play-btn svg,
.voice-play-btn::after,
.voice-play-btn::before { 
  display: none !important; 
  content: none !important;
}

.voice-waveform {
  flex: 0 0 35px !important; 
  width: 35px !important;
  min-width: 35px !important;
  max-width: 35px !important;
  height: 14px !important; 
  overflow: hidden !important;
  mask-image: linear-gradient(to right, #000 70%, transparent 100%);
  -webkit-mask-image: linear-gradient(to right, #000 70%, transparent 100%);
}

.voice-duration {
  font-size: 11px !important;
  margin-left: auto !important; 
}

.voice-download-btn {
  display: flex !important;
  transform: scale(0.85) !important;
  opacity: 0.6 !important;
}

.voice-transcription-toggle {
  position: absolute !important;
  top: 0 !important;
  left: 30px !important; 
  width: 50px !important;
  height: 32px !important; 
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  font-size: 0 !important; 
  padding: 0 !important;
  margin: 0 !important;
  opacity: 0 !important; 
  z-index: 10 !important; 
  cursor: pointer !important;
}
.voice-transcription-toggle svg { display: none !important; }
.voice-transcription-toggle::after { content: none !important; }

.voice-transcription {
  display: block !important;
  padding: var(--bubble-me-padding) !important;
  font-size: var(--bubble-me-font-size) !important;
  border-radius: var(--bubble-me-radius) !important;
  width: max-content !important;
  max-width: 100% !important;
  border: none !important; 
}
.msg-me .voice-transcription {
  background: var(--bubble-them-bg) !important;
  box-shadow: var(--bubble-them-shadow) !important;
  color: #a08c96 !important; 
}
.msg-them .voice-transcription {
  background: var(--bubble-me-bg) !important;
  box-shadow: var(--bubble-me-shadow) !important;
  color: #a08c96 !important; 
}

/* ---------- B. 引用分离 ---------- */
.msg-reply-block { display: none !important; }
.msg-reply-block-detached { display: flex !important; }

/* ---------- C. 翻译分离 ---------- */
.msg-translation-wrapper { display: none !important; }
.msg-translation-detached {
  display: flex !important;
  margin-top: 6px !important; 
  width: fit-content !important;
  max-width: 100% !important;
}
.msg-translation-detached-me { align-self: flex-end !important; }
.msg-translation-detached-them { align-self: flex-start !important; }
.msg-translation-detached-content {
  padding: var(--bubble-me-padding) !important;
  font-size: 13px !important;
  border-radius: var(--bubble-me-radius) !important;
  border: none !important; 
}

.msg-translation-detached-me .msg-translation-detached-content {
  background: var(--bubble-them-bg) !important; 
  color: #a08c96 !important; 
  box-shadow: var(--bubble-them-shadow) !important;
}
.msg-translation-detached-them .msg-translation-detached-content {
  background: var(--bubble-me-bg) !important; 
  color: #a08c96 !important;
  box-shadow: var(--bubble-me-shadow) !important;
}

.msg-translation-detached-content::before,
.msg-translation-detached-content::after {
  content: none !important;
  display: none !important;
}

/* ============================================
   底栏排版与贴纸
============================================ */
.input-area-custom {
  position: relative !important;
  margin: 0 !important; 
  border-radius: 0 !important; 
  width: 100% !important;
}

.input-btn-plus {
  transform: translateY(-8px) !important; 
  width: 28px !important;
  height: 28px !important;
  background-size: 22px 22px !important;
}

.input-area-custom::before {
  content: "";
  position: absolute;
  top: -28px;
  left: 20px;
  width: 44px;
  height: 36px;
  background-image: url('https://i.postimg.cc/cCrkpNhj/1786155676584.png');
  background-size: contain;
  background-position: bottom left;
  background-repeat: no-repeat;
  pointer-events: none;
  z-index: 10;
}

@keyframes sendSpin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

/* ============================================
   气泡与旁白贴纸
============================================ */
.msg-narration-custom {
  position: relative !important;
  overflow: visible !important;
  margin: 24px auto 12px !important;
}
.msg-narration-custom::after {
  content: "";
  position: absolute;
  top: -30px;
  left: 50%;
  transform: translateX(-50%);
  width: 48px;
  height: 38px;
  background-image: url('https://i.postimg.cc/6qXTS9Bx/1786086039172.png');
  background-size: contain;
  background-position: bottom center;
  background-repeat: no-repeat;
  pointer-events: none;
  z-index: 10;
}

.bubble-me-custom, .bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
}

/* 对方常规气泡贴纸 */
.bubble-them-custom::before {
  content: "";
  position: absolute;
  top: -20px;       
  right: -22px;     
  width: 42px;      
  height: 42px;     
  background-image: url('https://i.postimg.cc/5yVjGxfV/1786086032668.png');
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  pointer-events: none;
  z-index: 10;
}

/* 己方常规气泡贴纸 */
.bubble-me-custom::before {
  content: "";
  position: absolute;
  bottom: -18px; 
  left: -16px;
  width: 38px;
  height: 38px;
  background-image: url('https://i.postimg.cc/qqTgYkpp/1786085880827.png');
  background-size: contain;
  background-position: center;
  background-repeat: no-repeat;
  pointer-events: none;
  z-index: 10;
}

/* 屏蔽分离式外壳的贴纸 */
.msg-them .bubble-them-custom:has(.voice-msg)::before,
.msg-me .bubble-me-custom:has(.voice-msg)::before {
  display: none !important;
}
/* ============================================
   补丁：通用隔离法与完美缩小 (天才思路版)
============================================ */

/* 1. 通用反向隔离 (你的绝妙巧思)
   只要气泡内包含图片(img)、卡片组件(card)、语音(voice)，一律强行杀掉小狗和CHAR挂件素材！
   再也不用一个个写死类名了！ */
.bubble-me-custom:has(img)::before,
.bubble-them-custom:has(img)::before,
.bubble-me-custom:has([class*="card"])::before,
.bubble-them-custom:has([class*="card"])::before,
.bubble-me-custom:has(.voice-msg)::before,
.bubble-them-custom:has(.voice-msg)::before {
  display: none !important;
  content: none !important;
  background-image: none !important;
}

/* 扒掉这些特殊气泡的自带白底色和边框，只留内部本体 */
.bubble-me-custom:has(img),
.bubble-them-custom:has(img),
.bubble-me-custom:has([class*="card"]),
.bubble-them-custom:has([class*="card"]) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}

/* 2. 修复图片/文字图缩放：精准定位直接约束宽度 */
.msg-image-wrapper,
.bubble-me-custom.image,
.bubble-them-custom.image {
  max-width: 140px !important; /* 强制缩小极限尺寸 */
  border-radius: 12px !important;
  box-shadow: 0 2px 8px rgba(240, 224, 232, 0.4) !important;
  overflow: hidden !important;
}
.msg-image-wrapper img,
.bubble-me-custom.image img,
.bubble-them-custom.image img {
  width: 100% !important;
  height: auto !important;
  border-radius: 12px !important;
  display: block !important;
}

/* 3. 修复表情包：剥离阴影与圆角，保证边缘透明感 */
.bubble-me-custom.sticker,
.bubble-them-custom.sticker,
.bubble-me-custom:has(.emoji), 
.bubble-them-custom:has(.emoji) {
  max-width: 100px !important; /* 表情包压得比普通图片更小 */
  background: transparent !important;
  box-shadow: none !important;
  border-radius: 0 !important;
}
.bubble-me-custom.sticker img,
.bubble-them-custom.sticker img {
  width: 100% !important;
  height: auto !important;
}

/* 4. 修复卡片悬空与变远问题：使用自动布局收缩的 zoom 属性 */
.msg-transfer-card,
.msg-redpacket-card,
.msg-loc-card,
[class*="card"] {
  zoom: 0.85 !important; /* 核心魔法：缩小的同时完美自适应占位，绝不会悬空远离头像 */
  border-radius: 16px !important;
  box-shadow: 0 2px 10px rgba(240, 224, 232, 0.4) !important;
  overflow: hidden !important;
}

/* 兼容部分不支持 zoom 的安卓底层（双保险） */
@supports not (zoom: 0.85) {
  .msg-transfer-card,
  .msg-redpacket-card,
  .msg-loc-card,
  [class*="card"] {
    transform: scale(0.85) !important;
  }
  .msg-me [class*="card"] {
    transform-origin: right center !important;
    margin-right: -5% !important; /* 拉近与我方头像的距离 */
  }
  .msg-them [class*="card"] {
    transform-origin: left center !important;
    margin-left: -5% !important; /* 拉近与对方头像的距离 */
  }
}

