/* ═══════════════════════════════════════════════
   🌙 8. 自动夜间模式 (完美修复封面遮挡版)
   ═══════════════════════════════════════════════ */
[data-color-scheme="dark"] {
  --nj-msg-text: #e4e4e6;
  --nj-msg-text-muted: #8e8e93;
  --nj-msg-text-time: #666668;

  /* 注入给所有板块的黑化变量 */
  --nj-msg-bg: #000000;
  --nj-msg-profile-bg: #000000;
  --nj-msg-moments-bg: #000000;
  --nj-msg-fav-bg: #000000;
  --nj-msg-card-bg: #1c1c1e;
  --nj-msg-profile-name-color: #e4e4e6;
  --nj-msg-profile-hobby-chip-bg: #2c2c2e;
  --nj-msg-profile-hobby-chip-color: #e4e4e6;
  --nj-msg-moments-post-name-color: #8e8e93;

  /* 修复朋友圈评论区扎眼的白底 */
  --nj-msg-moments-comment-bg: #1c1c1e;
}

/* ★ 4个板块的大背景在夜间统统变成纯黑 ★ */
[data-color-scheme="dark"] #messaging-chat-tab,
[data-color-scheme="dark"] #messaging-moments-tab,
[data-color-scheme="dark"] #messaging-profile-tab,
[data-color-scheme="dark"] #messaging-favorites-tab {
  background-color: #000000 !important;
}

/* ⚠️ 仅对“聊天列表”的顶栏压暗，朋友圈/主页顶栏保持透明，不挡封面图！ */
[data-color-scheme="dark"] .nj-chat-tab-header {
  background-color: #1a1a1a !important;
  background-blend-mode: multiply !important;
  border-bottom-color: #2c2c2e !important;
  filter: brightness(0.9);
}

/* 朋友圈、主页、收藏的顶部文字、图标在夜间变成浅灰/白色 */
[data-color-scheme="dark"] .nj-moments-header svg,
[data-color-scheme="dark"] .nj-profile-tab-header svg,
[data-color-scheme="dark"] .nj-favorites-tab-header svg,
[data-color-scheme="dark"] .nj-favorites-tab-title {
  filter: brightness(0) invert(0.8) !important;
  color: #e4e4e6 !important;
}

/* ★ 强行黑化朋友圈评论区和文字 ★ */
[data-color-scheme="dark"] .nj-moments-engagement,
[data-color-scheme="dark"] .nj-moments-comment {
  background-color: #1c1c1e !important;
}
[data-color-scheme="dark"] .nj-moments-comment-content,
[data-color-scheme="dark"] .nj-moments-comment-author {
  color: #e4e4e6 !important;
}

/* 聊天列表手账装饰区压暗，避免大面积白板刺眼 */
[data-color-scheme="dark"] .nj-chat-tab-decor-top {
  filter: brightness(0.7) contrast(1.05);
}

/* 聊天顶栏胶囊和便签边框高级深色化 */
[data-color-scheme="dark"] .nj-chat-tab-header-title-btn,
[data-color-scheme="dark"] .nj-chat-tab-notes {
  border-color: #444 !important;
  background-color: rgba(255, 255, 255, 0.05) !important;
}
[data-color-scheme="dark"] .nj-chat-tab-header-title-btn::after {
  color: #d0d0d0 !important;
