}
.nook-chip svg { display: none !important; }

.nook-reader-title { display: none !important; }
.nook-reader-head .nook-icon-btn { pointer-events: auto !important; }

/* 去掉标题上下装饰 */
.nook-ch-orn, .nook-ch-rule { display: none !important; }

/* --- 章节排版微调区 --- */

.nook-ch-header {
  position: relative !important;
