  content: "";
  position: absolute !important;
  top: -30px !important;
  right: -18px !important;
  width: 194px !important;
  height: 200px !important;
  background-image: url('https://i.postimg.cc/qBs9F3H7/IMG-3806.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: right top !important;
  z-index: 1 !important;
  pointer-events: none !important;
}


.nook-buddy-bubble, .nook-buddy-name, .nook-buddy-status, .nook-buddy-meta {
  display: none !important;
}

/* 2. 头像框（左边竖排日期） */
.nook-buddy-avatar {
  position: fixed !important;
  left: 10px !important;
  bottom: 30px !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  width: auto !important;
  height: auto !important;
  overflow: visible !important;
}
.nook-buddy-avatar img {
  display: none !important;
}
.nook-buddy-avatar::after {
  content: "2026.6.10" !important;
  font-family: 'MyTitleFont', serif !important;
  font-size: 10px !important;
  color: rgba(0, 0, 0, 0.5) !important;
  writing-mode: vertical-rl !important;
  text-orientation: upright !important;
  letter-spacing: 6px !important;
}

/* 3. 底栏右边“聊聊这段”按钮 */
.nook-buddy-ask {
  position: fixed !important;
  right: 20px !important;
  bottom: 40px !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  color: transparent !important;
  overflow: visible !important;
}
.nook-buddy-ask svg {
  display: none !important;
}
.nook-buddy-ask::after {
