/*⁣⁠‌‍⁠​​‌​⁠‍⁠‍‌​​​‌‌‍​‌​​⁠⁠⁠​‍‍​‍‌‌​‌‌‌⁠‍‌⁠‍‌​‌‍​‍‍‍⁠​‍​‌‍⁠⁠‍​⁠⁠⁠‌⁣ ========================================================
   仿 iOS 简约风名册美化 · 整理版
   结构：变量 → 名册页 → 卡片 → 轮播 → 网格
         → 详情页（公共/入口/底栏/资料/备注/立绘/世界书）
         → 简洁版备忘录
   ======================================================== */

:root {
  /* 详情页玻璃按钮 */
  --rs-glass-bg: rgba(150, 150, 170, 0.35);
  --rs-glass-border: rgba(255, 255, 255, 0.75);
  --rs-glass-size: 44px;
  --rs-glass-blur: blur(14px) saturate(170%);
  --rs-glass-shadow:
    inset 0 1px 2px rgba(255, 255, 255, 0.6),
    0 3px 12px rgba(0, 0, 0, 0.1);
  --rs-glass-bg-on: rgba(255, 255, 255, 0.55);

  /* 详情页大卡片 */
  --rs-card-bg: rgba(255, 255, 255, 0.2);
  --rs-card-border: rgba(255, 255, 255, 0.35);
  --rs-card-blur: blur(16px) saturate(140%);
  --rs-line: rgba(255, 255, 255, 0.22);
  --rs-text: #ffffff;
  --rs-text-2: rgba(255, 255, 255, 0.65);

  /* 相册卡面按钮 */
  --pc-btn-bg: #ffffff;
  --pc-btn-ink: #1c1c1e;
  --pc-top-h: 44px;
  --pc-bot-h: 56px;
  --pc-bot-gap: 4px;

  /* 简洁版备忘录 */
  --rjs-bar-h: 44px;
  --rjs-bar-top: calc(var(--nuo-safe-top, env(safe-area-inset-top, 0px)) + 12px);
  --rjs-btn-bg: rgba(255, 255, 255, 0.96);
  --rjs-btn-shadow: 0 2px 14px rgba(0, 0, 0, 0.1), 0 0 1px rgba(0, 0, 0, 0.08);
  --rjs-chip-bg: #fdeadb;
  --rjs-chip-text: #f0913f;

  /* 名册布局：不锁 --roster-layout，保留顶栏视图切换键 */
  --roster-grid-min: 100%;
  --roster-card-ratio: auto;
  --roster-fab-rotate: 0deg;
  --roster-lift: 48px;
}

