.roster-view-carousel .rj-front::after {
  content: "" !important;
  display: block !important;
}

/* 备忘录里的大图也用了 .rj-front，不要把卡面按钮带过去 */
.rjs-jade .rj-front::after,
.rjs-overlay .rj-front::after,
.roster-view-carousel .rjs-jade .rj-front::after {
  content: none !important;
  display: none !important;
}


/* ========================================================
   三、轮播视图：iOS 相册风顶栏 / 底栏
   顶栏：左「图库」大字（返回键）/ 右 ≡ 圆钮 + 「选择」胶囊
   底栏：左 图库|精选集 胶囊（精选集 = 加号菜单）/ 右 搜索圆钮
   ======================================================== */

.roster-view-carousel .roster-header {
  padding-top: calc(var(--nuo-safe-top, env(safe-area-inset-top, 0px)) + 8px) !important;
  padding-left: 20px !important;
  padding-right: 16px !important;
  align-items: center !important;
}

.roster-view-carousel .roster-title { display: none !important; }

/* 返回键 → 左边大字「图库」 */
.roster-view-carousel .roster-btn-back {
  display: flex !important;
  align-items: center !important;
  width: auto !important;
  height: var(--pc-top-h) !important;
  min-width: 0 !important;
  max-width: none !important;
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  font-size: 0 !important;
  color: transparent !important;
}

.roster-view-carousel .roster-btn-back svg,
.roster-view-carousel .roster-btn-back i,
.roster-view-carousel .roster-btn-back img { display: none !important; }

.roster-view-carousel .roster-btn-back::before {
  content: none !important;
  display: none !important;
}

.roster-view-carousel .roster-btn-back::after {
