value.customCss:
.xt-root {
    --xt-bg: #ffffff;
    --xt-text: #1a1a1a;
    --xt-radius: 12px;
    --xt-radius-sm: 8px;
    padding: 6px;
    position: relative;
    background: var(--xt-bg);
    border: 2px solid #000;
    overflow-y: auto;
    overflow-x: hidden;
    max-height: 85vh;
}
.xt-root::-webkit-scrollbar { width: 6px; }
.xt-root::-webkit-scrollbar-track { background: #f0f0f0; }
.xt-root::-webkit-scrollbar-thumb { background: #333; border-radius: 3px; }

.xt-root > .xt-image:first-child {
    background: transparent !important;
    min-height: 100px !important;
    max-height: 150px !important;
    object-fit: contain !important;
    display: block !important;
}

.xt-row {
    display: flex !important;
    gap: 8px !important;
}
.xt-row > * {
    flex: 1 1 50% !important;
    max-width: 50% !important;
    min-width: 0 !important;
}
.xt-row .xt-image {
    background: transparent !important;
    height: 180px !important;
    max-height: 180px !important;
    min-height: 180px !important;
    width: 100% !important;
    object-fit: cover !important;
    border-radius: var(--xt-radius-sm);
    display: block !important;
}

