/*⁣⁠‌‍⁠​​‌​⁠‍⁠‍‌​​​‌‌‍​‌​​⁠⁠⁠​‍‍​‍‌‌​‌‌‌⁠‍‌⁠‍‌​‌‍​‍‍‍⁠​‍​‌‍⁠⁠‍​⁠⁠⁠‌⁣ ===== BuddyBuddy 背景 ===== */
.xt-root {
  --xt-text: #1a1a1a;
  /* 优先点阵与像素等宽字体栈 */
  --xt-font: 'SimSun', '宋体', 'Courier New', Monaco, monospace, sans-serif;
  background-image: url('https://imgbed.heliar.top/i/BqK1xa6a-rownuR0_IMG_20261001_191323.jpg');
  background-size: 100% 100%;
  background-position: center top;
  background-repeat: no-repeat;
