}
.xt-card:nth-of-type(4) .xt-card-title { display: none !important; }

/* 草稿文字区：限制高度 + 滑动滚轮 */
.xt-card:nth-of-type(4) .xt-text:first-of-type {
  display: block !important;
  position: static !important;
  background: transparent !important;
  border: none !important;
