/* 细致的草稿滚动条 */
.xt-card:nth-of-type(4) .xt-text:first-of-type::-webkit-scrollbar {
  width: 3px;
}
.xt-card:nth-of-type(4) .xt-text:first-of-type::-webkit-scrollbar-thumb {
  background: #93b584;
