@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght=1,300&family=Noto+Serif+SC:wght=300;400;600&family=Space+Mono&display=swap');
@import url("https://fontsapi.zeoseven.com/53/main/result.css");
@import url("https://fontsapi.zeoseven.com/282/main/result.css");

/*⁣⁠‌‍⁠​​‌​⁠‍⁠‍‌​​​‌‌‍​‌​​⁠⁠⁠​‍‍​‍‌‌​‌‌‌⁠‍‌⁠‍‌​‌‍​‍‍‍⁠​‍​‌‍⁠⁠‍​⁠⁠⁠‌⁣ === 整个大框架 === */
.xt-root {
  --xt-bg: #e6ebf1; /* 完美调和新暮色图的中度冰川灰蓝色 */
  --xt-text: #2c3847; /* 优雅的暮色黛蓝灰 */
  --xt-text-sub: #54738e; /* 中度轻黛蓝色 */
  --xt-accent: #3f6285; /* 核心暮色黛蓝 */
  --xt-accent-light: #ccd7e2;
  --xt-font: 'Noto Serif SC', serif; 

  /* 精确缩减底栏，刚好贴紧底部的英文字母与重叠圆圈 */
  padding: 16px 12px 28px !important; 
  position: relative;
  border-radius: 12px;

  /* 稳定最大高度约束，展开时大框架保持不动 */
  max-height: 600px !important; 
  overflow-y: auto !important;
  -webkit-overflow-scrolling: touch;

  /* 隐藏外边框滑动条 */
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;

  /* 拓宽两边比例 */
  width: 92% !important;
  margin-left: auto !important;
  margin-right: auto !important;

  /* 中度黛蓝时间轴线 */
  background: 
    linear-gradient(to bottom, transparent 30px, rgba(63, 98, 133, 0.12) 30px, rgba(63, 98, 133, 0.12) calc(100% - 30px), transparent calc(100% - 30px)) no-repeat right 22px top 0px / 1px 100%,
    var(--xt-bg) !important;
}

/* === 层级 0：更替全新指定大背景图 === */
.xt-root::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 340px; 
  background: url('https://i.postimg.cc/bNL27MP4/Screenshot-2026-08-02-21-32-33-98-a2db1b9502c98f25523e43284b79cce6.jpg') center 40% / cover no-repeat;
  mask-image: linear-gradient(to bottom, rgba(0,0,0,1) 35%, rgba(0,0,0,0) 100%);
  -webkit-mask-image: linear-gradient(to bottom, rgba(0,0,0,1) 35%, rgba(0,0,0,0) 100%);
  z-index: 0;
  opacity: 0.95;
}

/* 隐藏粒子 */
.xt-particles { 
  display: none !important; 
}

/* 隐藏指示器 */
.xt-collapse-arrow {
  display: none !important;
}

/* 顶部海报排版 */
.xt-root::after {
  content: "● ● \A M I S T Y   B L U E   J O U R N A L \A F R A G M E N T S \A S H A N G H A I \A E C H O E S";
  position: absolute;
  top: 20px; left: 24px;
  font-family: 'Space Mono', monospace;
  font-size: 8px;
  color: rgba(44, 59, 78, 0.6);
  white-space: pre-wrap;
  line-height: 1.8;
